442→    }
443→  }, [accessToken, coreKitLogout, clearAuthState, navigate, isLoggingOut]);
444→
445→  // Keep function refs up-to-date for use in session restoration effect.
446→  // Using refs prevents the effect from re-firing when function identities change.
447→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
448→  coreKitLogoutRef.current = coreKitLogout;
