 38→export type ApprovalStatus =
 39→  | 'idle'
 40→  | 'requesting'
 41→  | 'pending'
 42→  | 'approved'
 43→  | 'denied'
 44→  | 'expired'
 45→  | 'completing'
 46→  | 'error';
