async () => {
  // The coreKit is a module-scoped singleton. We can try to access it
  // through React internals or by finding the Zustand store.
  // Let's try the React fiber approach to find the coreKit from the context.

  const root = document.getElementById('root');
  const fiberKey = Object.keys(root).find(k => k.startsWith('__reactFiber'));
  if (!fiberKey) return { error: 'no React fiber found' };

  // Walk the fiber tree to find CoreKitContext provider
  let fiber = root[fiberKey];
  let coreKit = null;
  let depth = 0;
  const maxDepth = 200;

  function walkFiber(node) {
    if (!node || depth > maxDepth) return;
    depth++;

    // Check if this is a context provider with coreKit
    if (node.memoizedProps?.value?.coreKit) {
      coreKit = node.memoizedProps.value.coreKit;
      return;
    }
    if (node.pendingProps?.value?.coreKit) {
      coreKit = node.pendingProps.value.coreKit;
      return;
    }

    // Try child first, then sibling
    walkFiber(node.child);
    if (!coreKit) walkFiber(node.sibling);
  }

  walkFiber(fiber);

  if (!coreKit) {
    return { error: 'coreKit not found in fiber tree', depth };
  }

  try {
    const details = coreKit.getKeyDetails();
    return {
      status: coreKit.status,
      totalFactors: details.totalFactors,
      threshold: details.threshold,
      requiredFactors: details.requiredFactors,
      tssPubKey: details.tssPubKey ? {
        x: details.tssPubKey.x?.toString('hex'),
        y: details.tssPubKey.y?.toString('hex'),
      } : null,
      shareDescriptions: details.shareDescriptions,
    };
  } catch (e) {
    return { error: 'getKeyDetails failed: ' + e.message };
  }
}

