async () => {
  const root = document.getElementById('root');
  const containerKey = Object.keys(root).find(k => k.startsWith('__reactContainer'));
  if (!containerKey) return { error: 'no react container' };

  let fiber = root[containerKey];
  let coreKit = null;
  let depth = 0;
  const maxDepth = 300;

  function walkFiber(node) {
    if (!node || depth > maxDepth || coreKit) return;
    depth++;

    // Check memoizedState for context values (hooks chain)
    let hookState = node.memoizedState;
    let hookDepth = 0;
    while (hookState && hookDepth < 20) {
      if (hookState.queue?.lastRenderedState?.coreKit) {
        coreKit = hookState.queue.lastRenderedState.coreKit;
        return;
      }
      // Context consumers store in memoizedState directly sometimes
      if (hookState.memoizedState?.coreKit) {
        coreKit = hookState.memoizedState.coreKit;
        return;
      }
      hookState = hookState.next;
      hookDepth++;
    }

    // Check props
    if (node.memoizedProps?.value?.coreKit) {
      coreKit = node.memoizedProps.value.coreKit;
      return;
    }

    walkFiber(node.child);
    if (!coreKit) walkFiber(node.sibling);
  }

  walkFiber(fiber);

  if (!coreKit) {
    return { error: 'coreKit not found', depth };
  }

  const details = coreKit.getKeyDetails();

  // Serialize shareDescriptions carefully
  const sd = {};
  if (details.shareDescriptions) {
    for (const [key, val] of Object.entries(details.shareDescriptions)) {
      sd[key] = val;
    }
  }

  return {
    found: true,
    status: coreKit.status,
    totalFactors: details.totalFactors,
    threshold: details.threshold,
    requiredFactors: details.requiredFactors,
    shareDescriptions: sd,
  };
}

