  1→import { useCallback } from 'react';
  2→import {
  3→  COREKIT_STATUS,
  4→  generateFactorKey,
  5→  keyToMnemonic,
  6→  mnemonicToKey,
  7→  TssShareType,
  8→  FactorKeyTypeShareDescription,
  9→  factorKeyCurve,
 10→} from '@web3auth/mpc-core-kit';
 11→import { Point } from '@tkey/common-types';
 12→import BN from 'bn.js';
 13→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
 14→import { useMfaStore } from '../stores/mfa.store';
 15→
 16→export type FactorInfo = {
 17→  factorPubHex: string;
 18→  description: string;
 19→  type: string;
 20→  /** Additional metadata set during createFactor (e.g. deviceId, browserName) */
 21→  additionalMetadata?: Record<string, string>;
 22→};
 23→
 24→export function useMfa() {
 25→  const { coreKit, syncStatus } = useCoreKit();
 26→
 27→  const isMfaEnabled = useMfaStore((s) => s.isMfaEnabled);
 28→  const isEnrolling = useMfaStore((s) => s.isEnrolling);
 29→  const factorCount = useMfaStore((s) => s.factorCount);
 30→  const threshold = useMfaStore((s) => s.threshold);
 31→
 32→  /**
 33→   * Check MFA status from Core Kit key details.
 34→   * MFA is enabled when totalFactors >= 2.
 35→   */
 36→  const checkMfaStatus = useCallback((): {
 37→    isMfaEnabled: boolean;
 38→    totalFactors: number;
 39→    threshold: number;
 40→  } => {
 41→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
 42→      return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
 43→    }
 44→    try {
 45→      const details = coreKit.getKeyDetails();
 46→      const enabled = details.totalFactors >= 2;
 47→      useMfaStore.getState().setMfaEnabled(enabled);
 48→      useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);
 49→      return {
 50→        isMfaEnabled: enabled,
 51→        totalFactors: details.totalFactors,
 52→        threshold: details.threshold,
 53→      };
 54→    } catch {
 55→      return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
 56→    }
 57→  }, [coreKit]);
 58→
 59→  /**
 60→   * Enable MFA. Returns 24-word recovery mnemonic.
 61→   * CRITICAL: commitChanges() must be called before enableMFA() in manualSync mode.
 62→   */
 63→  const enableMfa = useCallback(async (): Promise<string> => {
 64→    if (!coreKit) throw new Error('Core Kit not initialized');
 65→    if (coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
 66→      throw new Error('Must be logged in to enable MFA');
 67→    }
 68→
 69→    const store = useMfaStore.getState();
 70→    if (store.isMfaEnabled) {
 71→      throw new Error('MFA is already enabled');
 72→    }
 73→
 74→    useMfaStore.getState().setEnrolling(true);
 75→    try {
 76→      // Commit any pending changes first (CRITICAL for manualSync mode -- Pitfall 1)
 77→      await coreKit.commitChanges();
 78→
 79→      // Capture TSS public key BEFORE enableMFA for stability verification (MFA-04)
 80→      const preMfaTssPub = coreKit.getKeyDetails().tssPubKey;
 81→
 82→      // enableMFA creates device factor + recovery factor atomically
 83→      const backupFactorKeyHex = await coreKit.enableMFA({});
 84→
 85→      // Commit the MFA changes
 86→      await coreKit.commitChanges();
 87→
 88→      // Defensive check: verify TSS public key unchanged after MFA enrollment (MFA-04)
 89→      const postMfaTssPub = coreKit.getKeyDetails().tssPubKey;
 90→      if (preMfaTssPub?.x && preMfaTssPub?.y && postMfaTssPub?.x && postMfaTssPub?.y) {
 91→        const preX = preMfaTssPub.x.toString('hex');
 92→        const preY = preMfaTssPub.y.toString('hex');
 93→        const postX = postMfaTssPub.x.toString('hex');
 94→        const postY = postMfaTssPub.y.toString('hex');
 95→        if (preX !== postX || preY !== postY) {
 96→          throw new Error(
 97→            'MFA enrollment failed: TSS public key changed. Your keypair identity is no longer stable. Please contact support.'
 98→          );
 99→        }
100→      }
101→
102→      // Convert to 24-word mnemonic for user display
103→      const mnemonic = keyToMnemonic(backupFactorKeyHex);
104→
105→      // Update store with new key details
106→      const details = coreKit.getKeyDetails();
107→      useMfaStore.getState().setMfaEnabled(true);
108→      useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);
109→
110→      return mnemonic;
111→    } finally {
112→      useMfaStore.getState().setEnrolling(false);
113→    }
114→  }, [coreKit]);
115→
116→  /**
117→   * Input a factor key (hex string) to complete REQUIRED_SHARE login.
118→   * Used for both recovery and cross-device approval flows.
119→   */
120→  const inputFactorKey = useCallback(
121→    async (factorKeyHex: string): Promise<void> => {
122→      if (!coreKit) throw new Error('Core Kit not initialized');
123→      const factorKey = new BN(factorKeyHex, 'hex');
124→      await coreKit.inputFactorKey(factorKey);
125→      syncStatus();
126→    },
127→    [coreKit, syncStatus]
128→  );
129→
130→  /**
131→   * Recover with a 24-word mnemonic phrase.
132→   * After recovery, creates a device factor for the new device.
133→   */
134→  const recoverWithMnemonic = useCallback(
135→    async (mnemonic: string): Promise<void> => {
136→      if (!coreKit) throw new Error('Core Kit not initialized');
137→
138→      // Convert mnemonic to factor key hex
139→      const factorKeyHex = mnemonicToKey(mnemonic.trim().toLowerCase());
140→      await inputFactorKey(factorKeyHex);
141→
142→      // Create a device factor for this new device
143→      const newDeviceFactor = generateFactorKey();
144→      await coreKit.createFactor({
145→        shareType: TssShareType.DEVICE,
146→        factorKey: newDeviceFactor.private,
147→        shareDescription: FactorKeyTypeShareDescription.DeviceShare,
148→      });
149→      await coreKit.setDeviceFactor(newDeviceFactor.private);
150→      await coreKit.commitChanges();
151→    },
152→    [coreKit, inputFactorKey]
153→  );
154→
155→  /**
156→   * Get all factors with their descriptions.
157→   * shareDescriptions is Record<string, string[]> where keys are factor pub hex.
158→   */
159→  const getFactors = useCallback((): FactorInfo[] => {
160→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return [];
161→    try {
162→      const details = coreKit.getKeyDetails();
163→      const factors: FactorInfo[] = [];
164→
165→      for (const [factorPubHex, descriptions] of Object.entries(details.shareDescriptions)) {
166→        for (const descJson of descriptions) {
167→          try {
168→            const parsed = JSON.parse(descJson) as {
169→              module?: string;
170→              additionalMetadata?: Record<string, string>;
171→            };
172→            factors.push({
173→              factorPubHex,
174→              description: parsed.module || 'unknown',
175→              type: parsed.module || 'unknown',
176→              additionalMetadata: parsed.additionalMetadata,
177→            });
178→          } catch {
179→            factors.push({
180→              factorPubHex,
181→              description: 'unknown',
182→              type: 'unknown',
183→            });
184→          }
185→        }
186→      }
187→
188→      return factors;
189→    } catch {
190→      return [];
191→    }
192→  }, [coreKit]);
193→
194→  /**
195→   * Delete a factor by its public key hex.
196→   * Cannot delete the currently active factor or the last remaining factor.
197→   */
198→  const deleteFactor = useCallback(
199→    async (factorPubHex: string): Promise<void> => {
200→      if (!coreKit) throw new Error('Core Kit not initialized');
201→      const factorPub = Point.fromSEC1(factorKeyCurve, factorPubHex);
202→      await coreKit.deleteFactor(factorPub);
203→      await coreKit.commitChanges();
204→    },
205→    [coreKit]
206→  );
207→
208→  /**
209→   * Get the current active factor key and share type.
210→   */
211→  const getCurrentFactorKey = useCallback((): {
212→    factorKey: BN;
213→    shareType: TssShareType;
214→  } | null => {
215→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return null;
216→    try {
217→      return coreKit.getCurrentFactorKey();
218→    } catch {
219→      return null;
220→    }
221→  }, [coreKit]);
222→
223→  /**
224→   * Regenerate the recovery phrase.
225→   * Deletes the old recovery factor and creates a new one.
226→   * Returns the new 24-word mnemonic.
227→   */
228→  const regenerateRecoveryPhrase = useCallback(async (): Promise<string> => {
229→    if (!coreKit) throw new Error('Core Kit not initialized');
230→    if (coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
231→      throw new Error('Must be logged in to regenerate recovery phrase');
232→    }
233→
234→    // Find the existing recovery (seedPhrase) factor
235→    const factors = getFactors();
236→    const recoveryFactor = factors.find((f) => f.type === FactorKeyTypeShareDescription.SeedPhrase);
237→
238→    if (recoveryFactor) {
239→      // Delete old recovery factor
240→      const factorPub = Point.fromSEC1(factorKeyCurve, recoveryFactor.factorPubHex);
241→      await coreKit.deleteFactor(factorPub);
242→    }
243→
244→    // Generate new recovery factor
245→    const newRecovery = generateFactorKey();
246→    await coreKit.createFactor({
247→      shareType: TssShareType.RECOVERY,
248→      factorKey: newRecovery.private,
249→      shareDescription: FactorKeyTypeShareDescription.SeedPhrase,
250→    });
251→    await coreKit.commitChanges();
252→
253→    // Convert the new factor key to mnemonic
254→    // Zero-pad to 64 hex chars (32 bytes)
255→    const factorKeyHex = newRecovery.private.toString('hex').padStart(64, '0');
256→    return keyToMnemonic(factorKeyHex);
257→  }, [coreKit, getFactors]);
258→
259→  return {
260→    // State from store
261→    isMfaEnabled,
262→    isEnrolling,
263→    factorCount,
264→    threshold,
265→
266→    // Operations
267→    checkMfaStatus,
268→    enableMfa,
269→    inputFactorKey,
270→    recoverWithMnemonic,
271→    getFactors,
272→    deleteFactor,
273→    getCurrentFactorKey,
274→    regenerateRecoveryPhrase,
275→  };
276→}
