  1→import { Injectable, UnauthorizedException } from '@nestjs/common';
  2→import * as jose from 'jose';
  3→
  4→const JWKS_URL = 'https://api-auth.web3auth.io/jwks';
  5→
  6→interface Web3AuthWallet {
  7→  type: string;
  8→  public_key?: string;
  9→  address?: string;
 10→  curve?: string;
 11→}
 12→
 13→interface Web3AuthPayload extends jose.JWTPayload {
 14→  wallets?: Web3AuthWallet[];
 15→  email?: string;
 16→  name?: string;
 17→  verifier?: string;
 18→  verifierId?: string;
 19→  aggregateVerifier?: string;
 20→}
 21→
 22→/**
 23→ * Verifies Web3Auth-issued JWTs against the Web3Auth JWKS endpoint.
 24→ * Used for verifying Core Kit session tokens when needed.
 25→ * Note: Primary auth flow uses CipherBox-issued JWTs verified by JwtIssuerService.
 26→ */
 27→@Injectable()
 28→export class Web3AuthVerifierService {
 29→  private jwks: jose.JWTVerifyGetKey | null = null;
 30→
 31→  private getJwks(): jose.JWTVerifyGetKey {
 32→    if (!this.jwks) {
 33→      this.jwks = jose.createRemoteJWKSet(new URL(JWKS_URL));
 34→    }
 35→    return this.jwks;
 36→  }
 37→
 38→  async verifyIdToken(idToken: string, expectedPublicKey: string): Promise<Web3AuthPayload> {
 39→    const jwks = this.getJwks();
 40→
 41→    let payload: Web3AuthPayload;
 42→    try {
 43→      const result = await jose.jwtVerify(idToken, jwks, {
 44→        algorithms: ['ES256'],
 45→      });
 46→      payload = result.payload as Web3AuthPayload;
 47→    } catch (error) {
 48→      throw new UnauthorizedException(
 49→        `Invalid Web3Auth token: ${error instanceof Error ? error.message : 'verification failed'}`
 50→      );
 51→    }
 52→
 53→    // Verify secp256k1 public key matches
 54→    const walletKey = payload.wallets?.find(
 55→      (w) => w.type === 'web3auth_app_key' && w.curve === 'secp256k1'
 56→    );
 57→    if (!walletKey?.public_key) {
 58→      throw new UnauthorizedException('No secp256k1 public key found in token');
 59→    }
 60→    if (walletKey.public_key !== expectedPublicKey) {
 61→      throw new UnauthorizedException('Public key mismatch');
 62→    }
 63→
 64→    return payload;
 65→  }
 66→
 67→  extractIdentifier(payload: Web3AuthPayload): string {
 68→    // Extract the most meaningful identifier from the payload
 69→    if (payload.email) {
 70→      return payload.email;
 71→    }
 72→    if (payload.verifierId) {
 73→      return payload.verifierId;
 74→    }
 75→    // Fallback to wallet address or public key
 76→    const wallet = payload.wallets?.[0];
 77→    if (wallet?.address) {
 78→      return wallet.address;
 79→    }
 80→    if (wallet?.public_key) {
 81→      return wallet.public_key;
 82→    }
 83→    throw new UnauthorizedException('No identifier found in token');
 84→  }
 85→
 86→  extractAuthMethodType(
 87→    payload: Web3AuthPayload
 88→  ): 'google' | 'apple' | 'github' | 'email' | 'wallet' {
 89→    // Detect auth method from verifier
 90→    const verifier = payload.verifier?.toLowerCase() || '';
 91→    const aggregateVerifier = payload.aggregateVerifier?.toLowerCase() || '';
 92→
 93→    if (verifier.includes('google') || aggregateVerifier.includes('google')) {
 94→      return 'google';
 95→    }
 96→    if (verifier.includes('apple') || aggregateVerifier.includes('apple')) {
 97→      return 'apple';
 98→    }
 99→    if (verifier.includes('github') || aggregateVerifier.includes('github')) {
100→      return 'github';
101→    }
102→    if (
103→      verifier.includes('email') ||
104→      verifier.includes('passwordless') ||
105→      aggregateVerifier.includes('email')
106→    ) {
107→      return 'email';
108→    }
109→
110→    // Default to email if email is present
111→    if (payload.email) {
112→      return 'email';
113→    }
114→
115→    // Fallback
116→    return 'email';
117→  }
118→}
