```typescript
async function doLoginWithCoreKit(
  coreKit: any,
  syncStatus: () => void,
  cipherboxJwt: string,
  userId: string
): Promise<CoreKitLoginResult> {
  const loginParams: any = {
    verifier: 'cipherbox-identity',        // Custom verifier registered with Web3Auth
    verifierId: userId,                     // User identifier
    idToken: cipherboxJwt,                 // JWT from CipherBox backend
