  await coreKit.loginWithJWT(loginParams);

  // Handle status
  if (coreKit.status === COREKIT_STATUS.LOGGED_IN) {
    await coreKit.commitChanges();         // Persist state to localStorage
    syncStatus();
    return 'logged_in';
  }

  if (coreKit.status === COREKIT_STATUS.REQUIRED_SHARE) {
    // MFA enabled but device lacks a factor
