### 4. Key Details Querying

**File:** `/Users/michael/Code/cipher-box/apps/web/src/hooks/useMfa.ts` (lines 37-58)

```typescript
const checkMfaStatus = useCallback((): {
  isMfaEnabled: boolean;
  totalFactors: number;
  threshold: number;
} => {
  if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
    return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
  }
  try {
    const details = coreKit.getKeyDetails();
    const enabled = details.totalFactors > 2;  // Any factors beyond JWT + hashedShare = MFA enabled
    useMfaStore.getState().setMfaEnabled(enabled);
    useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);
    return {
      isMfaEnabled: enabled,
      totalFactors: details.totalFactors,
      threshold: details.threshold,
    };
  } catch {
    return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
  }
}, [coreKit]);
```

#### Return Type Structure from `getKeyDetails()`:
```typescript
{
  isMfaEnabled: boolean,        // Computed: totalFactors > 2
  totalFactors: number,         // Total factor count (includes JWT verifier + hashedShare)
  threshold: number,            // Minimum factors required for key reconstruction
  tssPubKey: {
    x: BN,                      // Elliptic curve point X coordinate
    y: BN                       // Elliptic curve point Y coordinate
  },
  shareDescriptions: Record<
    string,                      // Factor public key (hex)
    string[]                     // Array of JSON-stringified descriptions
  >
}
```

#### Getting All Factors:

```typescript
const getFactors = useCallback((): FactorInfo[] => {
  if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return [];
  try {
    const details = coreKit.getKeyDetails();
    const factors: FactorInfo[] = [];

    // Iterate over shareDescriptions map
    for (const [factorPubHex, descriptions] of Object.entries(details.shareDescriptions)) {
      for (const descJson of descriptions) {
        try {
          const parsed = JSON.parse(descJson) as {
            module?: string;
            additionalMetadata?: Record<string, string>;
          };
          factors.push({
            factorPubHex,
            description: parsed.module || 'unknown',
            type: parsed.module || 'unknown',
            additionalMetadata: parsed.additionalMetadata,
          });
        } catch {
          factors.push({
            factorPubHex,
            description: 'unknown',
            type: 'unknown',
          });
        }
      }
    }

    return factors;
  } catch {
    return [];
  }
}, [coreKit]);
```

