### 6. Additional Critical Relationships

#### Backend JWT Issuance:

**File:** `/Users/michael/Code/cipher-box/apps/api/src/auth/services/jwt-issuer.service.ts`

```typescript
async signIdentityJwt(userId: string, email?: string): Promise<string> {
  const claims: Record<string, unknown> = { sub: userId };
  if (email) {
    claims.email = email;
  }
  return new jose.SignJWT(claims)
    .setProtectedHeader({ alg: 'RS256', kid: 'cipherbox-identity-1' })
    .setIssuer('cipherbox')
    .setAudience('web3auth')
    .setIssuedAt()
    .setExpirationTime('5m')
    .sign(this.privateKey);
}
```

#### Cross-Device Approval Flow (MFA REQUIRED_SHARE Resolution):

**File:** `/Users/michael/Code/cipher-box/apps/web/src/hooks/useDeviceApproval.ts`

When a new device logs in with MFA enabled but lacks a device factor, it enters `REQUIRED_SHARE` state and must:

1. **Request approval** from existing authenticated device:
```typescript
const requestApproval = useCallback(async () => {
  // 1. Generate ephemeral secp256k1 keypair
  const ephemeral = secp256k1.keygen();
  ephemeralPrivKeyRef.current = ephemeral.secretKey;
  const ephemeralPubKeyHex = bytesToHex(ephemeral.publicKey);

  // 2. Create bulletin board request with ephemeral public key
  const { requestId } = await deviceApprovalApi.createRequest({
    deviceId: deviceIdentity.deviceId,
    deviceName: deviceInfo.name,
    ephemeralPublicKey: ephemeralPubKeyHex,
  });

  // 3. Poll for approval status
  startRequesterPolling(requestId);
}, [startRequesterPolling, clearEphemeralKey]);
```

2. **Existing device approves** by ECIES-encrypting current factor key with requester's ephemeral public key:
```typescript
const approveRequest = useCallback(
  async (requestId: string, ephemeralPublicKeyHex: string) => {
    // Get current factor key
    const factorKeyResult = coreKit.getCurrentFactorKey();
    const factorKeyBytes = hexToBytes(factorKeyResult.factorKey.toString('hex').padStart(64, '0'));

    // ECIES-encrypt with requester's ephemeral public key
    const ephemeralPubKey = hexToBytes(ephemeralPublicKeyHex);
    const encrypted = await wrapKey(factorKeyBytes, ephemeralPubKey);

    // Send response
    await deviceApprovalApi.respond(requestId, {
      action: 'approve',
      encryptedFactorKey: bytesToHex(encrypted),
      respondedByDeviceId: deviceIdentity.deviceId,
    });
  },
  [coreKit]
);
```

3. **New device decrypts and completes login**:
```typescript
const handleApprovalSuccess = useCallback(
  async (encryptedFactorKeyHex: string) => {
    // 1. ECIES-decrypt with ephemeral private key
    const encrypted = hexToBytes(encryptedFactorKeyHex);
    const factorKeyBytes = await unwrapKey(encrypted, ephemeralPrivKeyRef.current);
    const factorKeyHex = bytesToHex(factorKeyBytes);

    // 2. Input the factor key to Core Kit
    await inputFactorKey(factorKeyHex);

    // 3. Create device factor for this new device
    const newDeviceFactor = generateFactorKey();
    await coreKit.createFactor({
      shareType: TssShareType.DEVICE,
      factorKey: newDeviceFactor.private,
      shareDescription: FactorKeyTypeShareDescription.DeviceShare,
    });
    await coreKit.setDeviceFactor(newDeviceFactor.private);
    await coreKit.commitChanges();

    // 4. Complete login flow
    await completeRequiredShare();
  },
  [coreKit, inputFactorKey, completeRequiredShare]
);
```

