 34→class TssSecurityQuestion {
 35→  constructor() {
 36→    _defineProperty(this, "storeDomainName", "tssSecurityQuestion");
 37→  }
 38→  async setSecurityQuestion(params) {
 39→    const {
 40→      mpcCoreKit,
 41→      question,
 42→      answer,
 43→      description
 44→    } = params;
 45→    let {
 46→      shareType
 47→    } = params;
 48→    if (!mpcCoreKit.tKey) {
 49→      throw new Error("Tkey not initialized, call init first.");
 50→    }
 51→    if (!question || !answer) {
 52→      throw new Error("question and answer are required");
 53→    }
 54→    const domainKey = `${this.storeDomainName}:${params.mpcCoreKit.tKey.tssTag}`;
 55→
 56→    // default using recovery index
 57→    if (!shareType) {
 58→      shareType = TssShareType.RECOVERY;
 59→    } else if (!VALID_SHARE_INDICES.includes(shareType)) {
 60→      throw new Error(`invalid share type: must be one of ${VALID_SHARE_INDICES}`);
 61→    }
 62→    // Check for existing security question
 63→    const tkey = mpcCoreKit.tKey;
 64→    const storeDomain = tkey.metadata.getGeneralStoreDomain(domainKey);
 65→    if (storeDomain && storeDomain.question) {
 66→      throw new Error("Security question already exists");
 67→    }
 68→
 69→    // const pubKey = Point.fromTkeyPoint(mpcCoreKit.tKey.getTSSPub()).toBufferSEC1(true).toString("hex");
 70→    const pubKey = tkey.getKeyDetails().pubKey.toSEC1(secp256k1, true).toString("hex") + tkey.tssTag;
 71→    let hash = keccak256(Buffer.from(answer + pubKey, "utf8"));
 72→    hash = hash.startsWith("0x") ? hash.slice(2) : hash;
 73→    const factorKeyBN = new BN(hash, "hex");
 74→    const descriptionFinal = _objectSpread({
 75→      question
 76→    }, description);
 77→    await mpcCoreKit.createFactor({
 78→      factorKey: factorKeyBN,
 79→      shareType,
 80→      shareDescription: FactorKeyTypeShareDescription.SecurityQuestions,
 81→      additionalMetadata: descriptionFinal
 82→    });
 83→    // set store domain
 84→    const tkeyPt = getPubKeyPoint(factorKeyBN, factorKeyCurve);
 85→    const factorPub = tkeyPt.toSEC1(factorKeyCurve, true).toString("hex");
 86→    const storeData = new TssSecurityQuestionStore(shareType.toString(), factorPub, question);
 87→    tkey.metadata.setGeneralStoreDomain(domainKey, storeData.toJSON());
 88→
 89→    // check for auto commit
 90→    if (!tkey.manualSync) await tkey._syncShareMetadata();
 91→    return factorKeyBN.toString("hex").padStart(64, "0");
 92→  }
 93→  async changeSecurityQuestion(params) {
 94→    const {
 95→      mpcCoreKit,
 96→      newQuestion,
 97→      newAnswer,
 98→      answer
 99→    } = params;
100→    if (!newQuestion || !newAnswer || !answer) {
101→      throw new Error("question and answer are required");
102→    }
103→    // Check for existing security question
104→    const tkey = mpcCoreKit.tKey;
105→    // const pubKey = Point.fromTkeyPoint(mpcCoreKit.tKey.getTSSPub()).toBufferSEC1(true).toString("hex");
106→    const pubKey = tkey.getKeyDetails().pubKey.toSEC1(secp256k1, true).toString("hex") + tkey.tssTag;
107→    const domainKey = `${this.storeDomainName}:${params.mpcCoreKit.tKey.tssTag}`;
108→    const storeDomain = tkey.metadata.getGeneralStoreDomain(domainKey);
109→    if (!storeDomain || !storeDomain.question) {
110→      throw new Error("Security question does not exists");
111→    }
112→    const store = TssSecurityQuestionStore.fromJSON(storeDomain);
113→    const preHash = answer + pubKey;
114→    let hash = keccak256(Buffer.from(preHash, "utf8"));
115→    hash = hash.startsWith("0x") ? hash.slice(2) : hash;
116→    const factorKeyBN = new BN(hash, "hex");
117→    const factorKeyPt = getPubKeyPoint(factorKeyBN, factorKeyCurve);
118→    if (factorKeyPt.toSEC1(factorKeyCurve, true).toString("hex") !== store.factorPublicKey) {
119→      throw new Error("Invalid answer");
120→    }
121→
122→    // create new factor key
123→    const prenewHash = newAnswer + pubKey;
124→    let newHash = keccak256(Buffer.from(prenewHash, "utf8"));
125→    newHash = newHash.startsWith("0x") ? newHash.slice(2) : newHash;
126→    const newAnswerBN = new BN(newHash, "hex");
127→    const newFactorPt = Point.fromScalar(newAnswerBN, factorKeyCurve);
128→    await mpcCoreKit.createFactor({
129→      factorKey: newAnswerBN,
130→      shareType: parseInt(store.shareIndex),
131→      shareDescription: FactorKeyTypeShareDescription.SecurityQuestions
132→    });
133→
134→    // update mpcCoreKit state to use new factor key during change password if mpc factor key is security question factor
135→    if (mpcCoreKit.state.factorKey.eq(factorKeyBN)) {
136→      await mpcCoreKit.inputFactorKey(newAnswerBN);
137→    }
138→    // delete after create factor to prevent last key issue
139→    // delete old factor key and device share
140→    await mpcCoreKit.deleteFactor(factorKeyPt, factorKeyBN);
141→    store.factorPublicKey = newFactorPt.toSEC1(factorKeyCurve, true).toString("hex");
142→    store.question = newQuestion;
143→    tkey.metadata.setGeneralStoreDomain(domainKey, store.toJSON());
144→
145→    // check for auto commit
146→    if (!tkey.manualSync) await tkey._syncShareMetadata();
147→  }
148→
149→  // Should we check with answer before deleting?
150→  async deleteSecurityQuestion(mpcCoreKit, deleteFactorKey = true) {
151→    if (!mpcCoreKit.tKey) {
152→      throw new Error("Tkey not initialized, call init first.");
153→    }
154→    const domainKey = `${this.storeDomainName}:${mpcCoreKit.tKey.tssTag}`;
155→    const tkey = mpcCoreKit.tKey;
156→    if (deleteFactorKey) {
157→      const storeDomain = tkey.metadata.getGeneralStoreDomain(domainKey);
158→      if (!storeDomain || !storeDomain.question) {
159→        throw new Error("Security question does not exists");
160→      }
161→      const store = TssSecurityQuestionStore.fromJSON(storeDomain);
162→      if (store.factorPublicKey) {
163→        await mpcCoreKit.deleteFactor(Point.fromSEC1(factorKeyCurve, store.factorPublicKey));
164→      }
165→    }
166→    tkey.metadata.deleteGeneralStoreDomain(domainKey);
167→    // check for auto commit
168→    if (!tkey.manualSync) await tkey._syncShareMetadata();
169→  }
170→  async recoverFactor(mpcCoreKit, answer) {
171→    if (!mpcCoreKit.tKey) {
172→      throw new Error("Tkey not initialized, call init first.");
173→    }
174→    if (!answer) {
175→      throw new Error("question and answer are required");
176→    }
177→    const tkey = mpcCoreKit.tKey;
178→    const domainKey = `${this.storeDomainName}:${mpcCoreKit.tKey.tssTag}`;
179→    const storeDomain = tkey.metadata.getGeneralStoreDomain(domainKey);
180→    if (!storeDomain || !storeDomain.question) {
181→      throw new Error("Security question does not exists");
182→    }
183→    const store = TssSecurityQuestionStore.fromJSON(storeDomain);
184→
185→    // const pubKey = Point.fromTkeyPoint(mpcCoreKit.tKey.getTSSPub()).toBufferSEC1(true).toString("hex");
186→    const pubKey = tkey.getKeyDetails().pubKey.toSEC1(secp256k1, true).toString("hex") + tkey.tssTag;
187→    let hash = keccak256(Buffer.from(answer + pubKey, "utf8"));
188→    hash = hash.startsWith("0x") ? hash.slice(2) : hash;
189→    const factorKeyBN = new BN(hash, "hex");
190→    const factorKeyPt = Point.fromScalar(factorKeyBN, factorKeyCurve);
191→    if (factorKeyPt.toSEC1(factorKeyCurve, true).toString("hex") !== store.factorPublicKey) {
192→      throw new Error("Invalid answer");
193→    }
194→    return hash;
195→  }
196→  getQuestion(mpcCoreKit) {
197→    if (!mpcCoreKit.tKey) {
198→      throw new Error("Tkey not initialized, call init first.");
199→    }
200→    const tkey = mpcCoreKit.tKey;
201→    const domainKey = `${this.storeDomainName}:${mpcCoreKit.tKey.tssTag}`;
202→    const storeDomain = tkey.metadata.getGeneralStoreDomain(domainKey);
203→    if (!storeDomain || !storeDomain.question) {
204→      throw new Error("Security question does not exists");
205→    }
206→    const store = TssSecurityQuestionStore.fromJSON(storeDomain);
207→    return store.question;
208→  }
209→}
